import fs from 'node:fs';
const night = JSON.parse(fs.readFileSync('night.json','utf8'));
const plan = JSON.parse(fs.readFileSync('shift-plan.json','utf8'));
const rel = JSON.parse(fs.readFileSync('release.json','utf8'));
const rec = JSON.parse(fs.readFileSync('operations/original-receipt.json','utf8'));
const eta = night.efficiency, h = night.slotHours;
const dep = night.buses.map(b => {
  let ac = 0;
  for (let s=b.fromSlot; s<b.untilSlot; s++) ac += plan.acKw[s]*h;
  return b.startKwh + ac*eta;
});
const margins = night.buses.map((b,i)=> dep[i]-b.requiredKwh);
console.log(JSON.stringify({dep, margins, release:rel, limits:rec.limits, within:plan.acKw.every((k,i)=>k<=rec.limits[i]), evidenceMatches: rel.evidenceSha===rec.sha}, null, 2));
EOF

